namespace Switch2ProManager.Protocol;

/// <summary>
/// 440 Hz test tone (3 s) pre-encoded with libopus: CBR, 20 ms frames, 48 kHz, mono, CELT fullband (TOC 0xF8).
///  - Get():   100-byte packets (40 kbps): the format the controller's microphone path emits.
///  - Get50(): self-contained 50-byte packets (20 kbps), to test whether the output path expects standalone packets.
/// "Quiet" is about -38 dBFS, "normal" about -26 dBFS. Regenerate with research/tools/make_tone_packets.py.
/// </summary>
public static class TonePackets
{
    private const string Quiet100 = "";
    private const string Normal100 = "";
    private const string Quiet50 = "";
    private const string Normal50 = "";

    public static byte[][] Get(bool normal) => Split(Convert.FromBase64String(normal ? Normal100 : Quiet100), 100);
    public static byte[][] Get50(bool normal) => Split(Convert.FromBase64String(normal ? Normal50 : Quiet50), 50);

    private static byte[][] Split(byte[] all, int size)
    {
        var list = new List<byte[]>();
        for (int i = 0; i + size <= all.Length; i += size) list.Add(all[i..(i + size)]);
        return list.ToArray();
    }
}
